-- MP-0027: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='pas' and type='party') then raise exception 'MP-0027: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='umno' and type='party') then raise exception 'MP-0027: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('sh-mohmed-puzi-sh-ali','ismail-abd-muttalib','kamal-ashaari') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0027: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('pekan','maran','kuala krau') and slug not in ('sh-mohmed-puzi-sh-ali','ismail-abd-muttalib','kamal-ashaari')) then raise exception 'MP-0027: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0027:%' and (m.source_type <> 'editorial' or e.slug not in ('sh-mohmed-puzi-sh-ali','ismail-abd-muttalib','kamal-ashaari') or m.import_key not like 'MP-0027:' || e.slug || ':%')) then raise exception 'MP-0027: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'sh-mohmed-puzi-sh-ali','Sh Mohmed Puzi Sh Ali','government','Member of the Dewan Rakyat','Pekan','Pahang','Sh Mohmed Puzi Sh Ali represents Pekan, Pahang, in the Dewan Rakyat. A UMNO member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4124','/portraits/sh-mohmed-puzi-sh-ali.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P085.png','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4124"}, {"label": "UMNO · Pekan representative, party statement", "url": "https://umno-online.my/2024/01/01/umno-kekal-falsafah-perjuangannya-walaupun-berbeza-politik-dalam-kerajaan-madani-mohmed-puzi/"}, {"label": "UMNO · Pekan representation, 19 April 2026", "url": "https://umno-online.my/2026/04/19/lima-generasi-pemuda-umno-pekan-terus-perkukuh-parti/"}]'::jsonb from public.entities parent where parent.slug='umno' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'ismail-abd-muttalib','Ismail Abd Muttalib','opposition','Member of the Dewan Rakyat','Maran','Pahang','Ismail Abd Muttalib represents Maran, Pahang, in the Dewan Rakyat. A PAS member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4125','/portraits/ismail-abd-muttalib.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P086.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4125"}, {"label": "PAS · parliamentary representatives", "url": "https://pas.org.my/ahli-parlimen-pas-pru-ke-15/"}]'::jsonb from public.entities parent where parent.slug='pas' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'kamal-ashaari','Kamal Ashaari','opposition','Member of the Dewan Rakyat','Kuala Krau','Pahang','Kamal Ashaari represents Kuala Krau, Pahang, in the Dewan Rakyat. A PAS member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4126','/portraits/kamal-ashaari.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P087.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4126"}, {"label": "PAS · parliamentary representatives", "url": "https://pas.org.my/ahli-parlimen-pas-pru-ke-15/"}]'::jsonb from public.entities parent where parent.slug='pas' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('sh-mohmed-puzi-sh-ali','ismail-abd-muttalib','kamal-ashaari') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0027: concurrent ownership or identity change'; end if; end $$;

commit;
